package com.tainted.authuser.blackbox;

import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;
import io.restassured.RestAssured;
import io.restassured.response.Response;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Black-Box API Integration Test
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/guest
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthGuestBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String REDIS_URI = System.getProperty("test.redis.uri", "redis://localhost:6379/0");
    private static final String REDIS_TOKEN_PREFIX = "auth:token:";
    private static final long CONFIGURED_TTL_SECONDS = 3600L;

    private static final String UUID_PATTERN =
            "[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}";

    private static RedisClient redisClient;

    @BeforeAll
    static void startClients() {
        redisClient = RedisClient.create(REDIS_URI);
    }

    @AfterAll
    static void stopClients() {
        if (redisClient != null) {
            redisClient.shutdown();
        }
    }

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = AuthGuestBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private void teardownUsers(Set<String> userIds) {
        for (String id : userIds) {
            if (id == null) continue;
            executeSqlTemplate("sql/auth-guest-teardown.sql", Map.of("ID", id));
        }
    }

    /** Resolves the server-generated userId from the Redis auth:token:<token> mapping. */
    private String resolveUserId(RedisCommands<String, String> redis, String accessToken) {
        String userId = redis.get(REDIS_TOKEN_PREFIX + accessToken);
        assertNotNull(userId, "token must resolve to a userId in Redis right after guest() issues it");
        return userId;
    }

    @Test
    void NTC_guest_success_returnsTokenAndPersistsUser() throws Exception {
        Set<String> createdIds = new HashSet<>();
        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> redis = conn.sync();

            Response response = given().log().all()
                    .baseUri(BASE_URL)
                .when()
                    .post("/api/v1/auth/guest")
                .then().log().all()
                    .statusCode(200)
                    .body("accessToken", matchesPattern(UUID_PATTERN))
                    .body("displayName", equalTo("익명"))
                    .extract().response();

            String accessToken = response.jsonPath().getString("accessToken");
            String userId = resolveUserId(redis, accessToken);
            createdIds.add(userId);

            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT social_provider, external_id, created_at FROM user_account WHERE id = ?")) {
                ps.setString(1, userId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next(), "guest() must persist a UserAccount row for the resolved id");
                assertEquals("guest", rs.getString("social_provider"));
                assertTrue(rs.getString("external_id").matches("guest:" + UUID_PATTERN),
                        "external_id must be 'guest:' + a random UUID from idGenerator.newId()");
                assertNotNull(rs.getTimestamp("created_at"));
            }
        } finally {
            teardownUsers(createdIds);
        }
    }

    @Test
    void NTC_guest_multipleCalls_createDistinctUsers() throws Exception {
        Set<String> createdIds = new HashSet<>();
        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> redis = conn.sync();

            Response first = given().baseUri(BASE_URL).when().post("/api/v1/auth/guest")
                    .then().statusCode(200).extract().response();
            Response second = given().baseUri(BASE_URL).when().post("/api/v1/auth/guest")
                    .then().statusCode(200).extract().response();

            String firstToken = first.jsonPath().getString("accessToken");
            String secondToken = second.jsonPath().getString("accessToken");
            assertNotEquals(firstToken, secondToken, "each guest() call must issue a fresh token");

            String firstUserId = resolveUserId(redis, firstToken);
            String secondUserId = resolveUserId(redis, secondToken);
            createdIds.add(firstUserId);
            createdIds.add(secondUserId);
            assertNotEquals(firstUserId, secondUserId, "each guest() call must persist a distinct UserAccount");

            try (Connection dbConn = getDbConnection();
                 PreparedStatement ps = dbConn.prepareStatement(
                         "SELECT COUNT(*) FROM user_account WHERE id IN (?, ?) AND social_provider = 'guest'")) {
                ps.setString(1, firstUserId);
                ps.setString(2, secondUserId);
                ResultSet rs = ps.executeQuery();
                assertTrue(rs.next());
                assertEquals(2, rs.getInt(1));
            }
        } finally {
            teardownUsers(createdIds);
        }
    }

    @Test
    void NTC_guest_tokenTtlWithinConfiguredRange() throws Exception {
        Set<String> createdIds = new HashSet<>();
        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> redis = conn.sync();

            Response response = given().baseUri(BASE_URL).when().post("/api/v1/auth/guest")
                    .then().statusCode(200).extract().response();
            String accessToken = response.jsonPath().getString("accessToken");
            String userId = resolveUserId(redis, accessToken);
            createdIds.add(userId);

            Long ttl = redis.ttl(REDIS_TOKEN_PREFIX + accessToken);
            assertNotNull(ttl);
            // auth.token-ttl-seconds=3600 (application.yml); ttl must be freshly set, not -1 (no expiry) or -2 (missing).
            assertTrue(ttl > 0 && ttl <= CONFIGURED_TTL_SECONDS,
                    "ttl=" + ttl + " must be within (0, " + CONFIGURED_TTL_SECONDS + "]");
        } finally {
            teardownUsers(createdIds);
        }
    }

    @Test
    void ATC_guest_wrongHttpMethod_returns405() {
        given().log().all()
                .baseUri(BASE_URL)
            .when()
                .get("/api/v1/auth/guest")
            .then().log().all()
                .statusCode(405);
    }
}

