package com.tainted.authuser.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;
import static org.junit.jupiter.api.Assertions.*;

/**
 * Black-Box API Integration Test
 *
 * @target-controller InternalAuthController (src/main/java/com/tainted/authuser/web/InternalAuthController.java)
 * @target-api GET /internal/users/{id}
 *
 * `id` is a genuine DB_WHERE RED param (repository.findById(id)), so the full VTC standard-rule
 * table applies. UserAccount.id column is VARCHAR(64) (see UserAccount entity), used for
 * LENGTH_EXCEEDED/LENGTH_SHRUNK. No auth, no external HTTP calls -> no WireMock stub needed.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class UsersGetBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private String testId(TestInfo info) {
        return String.format("t%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = UsersGetBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private void teardown(String id) {
        executeSqlTemplate("sql/users-get-teardown.sql", Map.of("ID", id));
    }

    private void seed(String id, String socialProvider, String externalId, String createdAt) {
        executeSqlTemplate("sql/users-get-setup.sql", Map.of(
                "ID", id, "SOCIAL_PROVIDER", socialProvider, "EXTERNAL_ID", externalId, "CREATED_AT", createdAt));
    }

    /** Reads back the created_at TIMESTAMP the test itself just inserted, as UserResponse.createdAt (Instant.toString()) would render it. */
    private String expectedCreatedAt(String id) throws Exception {
        try (Connection conn = getDbConnection();
             PreparedStatement ps = conn.prepareStatement("SELECT created_at FROM user_account WHERE id = ?")) {
            ps.setString(1, id);
            ResultSet rs = ps.executeQuery();
            assertTrue(rs.next());
            return rs.getTimestamp("created_at").toInstant().toString();
        }
    }

    // ---------------------------------------------------------------- NTC ----

    @Test
    void NTC_getUser_found_returnsUserData(TestInfo info) throws Exception {
        String id = "T-" + testId(info);
        String externalId = "kakao:" + testId(info);
        teardown(id);
        seed(id, "kakao", externalId, "2026-01-15 10:30:00");

        try {
            String expectedCreatedAt = expectedCreatedAt(id);

            given().log().all()
                    .baseUri(BASE_URL)
                .when()
                    .get("/internal/users/{id}", id)
                .then().log().all()
                    .statusCode(200)
                    .body("id", equalTo(id))
                    .body("socialProvider", equalTo("kakao"))
                    .body("createdAt", equalTo(expectedCreatedAt));
        } finally {
            teardown(id);
        }
    }

    @Test
    void NTC_getUser_found_differentProvider_returnsUserData(TestInfo info) throws Exception {
        String id = "G-" + testId(info);
        String externalId = "google:" + testId(info);
        teardown(id);
        seed(id, "google", externalId, "2025-06-01 00:00:00");

        try {
            String expectedCreatedAt = expectedCreatedAt(id);

            given().baseUri(BASE_URL)
                .when()
                    .get("/internal/users/{id}", id)
                .then()
                    .statusCode(200)
                    .body("id", equalTo(id))
                    .body("socialProvider", equalTo("google"))
                    .body("createdAt", equalTo(expectedCreatedAt));
        } finally {
            teardown(id);
        }
    }

    @Test
    void NTC_getUser_idAtMaxDdlLength_returnsUserData(TestInfo info) throws Exception {
        // UserAccount.id is VARCHAR(64) — boundary case: id exactly 64 chars long still resolves.
        String suffix = testId(info);
        String id = ("MAXLEN-" + suffix + "-").repeat(1);
        id = id + "x".repeat(64 - id.length());
        assertEquals(64, id.length());
        String externalId = "naver:" + suffix;
        teardown(id);
        seed(id, "naver", externalId, "2026-03-20 08:15:30");

        try {
            String expectedCreatedAt = expectedCreatedAt(id);

            given().baseUri(BASE_URL)
                .when()
                    .get("/internal/users/{id}", id)
                .then()
                    .statusCode(200)
                    .body("id", equalTo(id))
                    .body("socialProvider", equalTo("naver"))
                    .body("createdAt", equalTo(expectedCreatedAt));
        } finally {
            teardown(id);
        }
    }

    // ---------------------------------------------------------------- ATC ----

    @Test
    void ATC_getUser_wrongHttpMethod_returns405(TestInfo info) {
        String id = "M-" + testId(info);
        given().log().all()
                .baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{}")
            .when()
                .post("/internal/users/{id}", id)
            .then().log().all()
                .statusCode(405);
    }

    // ---------------------------------------------------------------- VTC ----

    @Test
    void VTC_id_NULL() {
        // No {id} path segment at all -> route doesn't match GET /internal/users/{id}.
        given().log().all()
                .baseUri(BASE_URL)
            .when()
                .get("/internal/users")
            .then().log().all()
                .statusCode(404);
    }

    @Test
    void VTC_id_EMPTY() {
