import io.lettuce.core.RedisClient;
import io.lettuce.core.api.StatefulRedisConnection;
import io.lettuce.core.api.sync.RedisCommands;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.Statement;
import java.time.Duration;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.*;

/**
 * Black-Box API Integration Test
 *
 * @target-controller MeController (src/main/java/com/tainted/authuser/web/MeController.java)
 * @target-api GET /api/v1/me
 *
 * Auth here is hand-rolled in MeController.extractBearer() (no Spring interceptor, so
 * analyze-auth-flow correctly reports auth_type=none but there IS a real 401 branch).
 * The RED "parameter" is the Authorization header value / extracted bearer token, not a JSON
 * body field, so the VTC standard rule is applied to header variations instead. No external
 * HTTP calls -> no WireMock stub needed.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class MeGetBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8081");

    private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/authuser");
    private static final String DB_USER = System.getProperty("test.db.user", "root");
    private static final String DB_PASSWORD = System.getProperty("test.db.password", "rootpw");

    private static final String REDIS_URI = System.getProperty("test.redis.uri", "redis://localhost:6379/0");
    private static final String REDIS_TOKEN_PREFIX = "auth:token:";

    private static RedisClient redisClient;

    @BeforeAll
    static void startClients() {
        redisClient = RedisClient.create(REDIS_URI);
    }

    @AfterAll
    static void stopClients() {
        if (redisClient != null) {
            redisClient.shutdown();
        }
    }

    private String testId(TestInfo info) {
        return String.format("t%09d",
                Math.abs(info.getTestMethod().get().getName().hashCode()) % 1_000_000_000);
    }

    private static Connection getDbConnection() throws Exception {
        return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
    }

    private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
        try (Connection conn = getDbConnection();
             InputStream is = MeGetBlackBoxTest.class
                     .getClassLoader().getResourceAsStream(resourcePath);
             Statement stmt = conn.createStatement()) {
            String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
            for (var entry : params.entrySet()) {
                sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
            }
            for (String line : sql.split("\n")) {
                String trimmed = line.trim();
                if (trimmed.startsWith("--") || trimmed.isEmpty()) continue;
                if (trimmed.endsWith(";")) trimmed = trimmed.substring(0, trimmed.length() - 1);
                if (!trimmed.isEmpty()) stmt.execute(trimmed);
            }
        } catch (Exception e) {
            throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
        }
    }

    private void teardown(String id) {
        executeSqlTemplate("sql/me-get-teardown.sql", Map.of("ID", id));
    }

    private void seed(String id, String socialProvider, String externalId) {
        executeSqlTemplate("sql/me-get-setup.sql", Map.of("ID", id, "SOCIAL_PROVIDER", socialProvider, "EXTERNAL_ID", externalId));
    }

    // ---------------------------------------------------------------- NTC ----

    @Test
    void NTC_me_validBearer_google_returnsUserData(TestInfo info) throws Exception {
        String seed = testId(info);
        String id = "T-" + seed;
        String token = "tok-" + seed;
        teardown(id);
        seed(id, "google", "google:" + seed);

        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> redis = conn.sync();
            redis.setex(REDIS_TOKEN_PREFIX + token, Duration.ofSeconds(3600).getSeconds(), id);

            try {
                given().log().all()
                        .baseUri(BASE_URL)
                        .header("Authorization", "Bearer " + token)
                    .when()
                        .get("/api/v1/me")
                    .then().log().all()
                        .statusCode(200)
                        .body("userId", equalTo(id))
                        .body("displayName", equalTo("익명"))
                        .body("socialProvider", equalTo("google"));
            } finally {
                redis.del(REDIS_TOKEN_PREFIX + token);
            }
        } finally {
            teardown(id);
        }
    }

    @Test
    void NTC_me_validBearer_kakao_returnsUserData(TestInfo info) throws Exception {
        String seed = testId(info);
        String id = "K-" + seed;
        String token = "tok-" + seed;
        teardown(id);
        seed(id, "kakao", "kakao:" + seed);

        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> redis = conn.sync();
            redis.setex(REDIS_TOKEN_PREFIX + token, Duration.ofSeconds(3600).getSeconds(), id);

            try {
                given().baseUri(BASE_URL)
                        .header("Authorization", "Bearer " + token)
                    .when()
                        .get("/api/v1/me")
                    .then()
                        .statusCode(200)
                        .body("userId", equalTo(id))
                        .body("displayName", equalTo("익명"))
                        .body("socialProvider", equalTo("kakao"));
            } finally {
                redis.del(REDIS_TOKEN_PREFIX + token);
            }
        } finally {
            teardown(id);
        }
    }

    @Test
    void NTC_me_validBearer_naver_returnsUserData(TestInfo info) throws Exception {
        String seed = testId(info);
        String id = "N-" + seed;
        String token = "tok-" + seed;
        teardown(id);
        seed(id, "naver", "naver:" + seed);

        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> redis = conn.sync();
            redis.setex(REDIS_TOKEN_PREFIX + token, Duration.ofSeconds(3600).getSeconds(), id);

            try {
                given().baseUri(BASE_URL)
                        .header("Authorization", "Bearer " + token)
                    .when()
                        .get("/api/v1/me")
                    .then()
                        .statusCode(200)
                        .body("userId", equalTo(id))
                        .body("displayName", equalTo("익명"))
                        .body("socialProvider", equalTo("naver"));
            } finally {
                redis.del(REDIS_TOKEN_PREFIX + token);
            }
        } finally {
            teardown(id);
        }
    }

    // ---------------------------------------------------------------- ATC ----

    @Test
    void ATC_me_nonBearerScheme_returns401() {
        given().log().all()
                .baseUri(BASE_URL)
                .header("Authorization", "Basic abc")
            .when()
                .get("/api/v1/me")
            .then().log().all()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("missing bearer token"));
    }

    @Test
    void ATC_me_unknownToken_returns401(TestInfo info) {
        String unknownToken = "never-issued-" + testId(info);

        given().baseUri(BASE_URL)
                .header("Authorization", "Bearer " + unknownToken)
            .when()
                .get("/api/v1/me")
            .then()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("invalid or expired token"));
    }

    @Test
    void ATC_me_tokenResolvesButUserRowGone_returns404(TestInfo info) throws Exception {
        String seed = testId(info);
        String token = "orphan-tok-" + seed;
        String ghostId = "ghost-" + seed;

        try (StatefulRedisConnection<String, String> conn = redisClient.connect()) {
            RedisCommands<String, String> redis = conn.sync();
            // Redis resolves the token, but no user_account row exists for ghostId ->
            // repository.findById(...) is empty -> UserNotFoundException (unlike verify(),
            // which never throws and would just report active=false for the same setup).
            redis.setex(REDIS_TOKEN_PREFIX + token, Duration.ofSeconds(3600).getSeconds(), ghostId);

            try {
                given().baseUri(BASE_URL)
                        .header("Authorization", "Bearer " + token)
                    .when()
                        .get("/api/v1/me")
                    .then()
                        .statusCode(404)
                        .contentType(containsString("application/problem+json"))
                        .body("title", equalTo("User not found"))
                        .body("detail", equalTo("user not found: " + ghostId));
            } finally {
                redis.del(REDIS_TOKEN_PREFIX + token);
            }
        }
    }

    // ---------------------------------------------------------------- VTC ----
    // RED "parameter" = Authorization header / extracted bearer token. Standard NULL/EMPTY/
    // WHITE_SPACE rule applied to header variations instead of a JSON body field.

    @Test
    void VTC_authorizationHeader_NULL() {
        // No Authorization header at all.
        given().baseUri(BASE_URL)
            .when()
                .get("/api/v1/me")
            .then()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("missing bearer token"));
    }

    @Test
    void VTC_authorizationHeader_EMPTY() {
        given().baseUri(BASE_URL)
                .header("Authorization", "")
            .when()
                .get("/api/v1/me")
            .then()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("missing bearer token"));
    }

    @Test
    void VTC_bearerToken_EMPTY() {
        // "Bearer " prefix present, token part empty -> extractBearer succeeds (returns ""),
        // but TokenService.resolveUserId("") short-circuits on isBlank() -> InvalidTokenException.
        given().baseUri(BASE_URL)
                .header("Authorization", "Bearer ")
            .when()
                .get("/api/v1/me")
            .then()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("invalid or expired token"));
    }

    @Test
    void VTC_bearerToken_WHITE_SPACE() {
        given().baseUri(BASE_URL)
                .header("Authorization", "Bearer    ")
            .when()
                .get("/api/v1/me")
            .then()
                .statusCode(401)
                .contentType(containsString("application/problem+json"))
                .body("title", equalTo("Invalid token"))
                .body("detail", equalTo("invalid or expired token"));
    }
}

